#include <stdio.h>
#include <string.h>
#include "../wiegand_format.h"

int main(int argc, char** argv) {
    if(argc != 2) return 2;
    bool bits[256];
    int n = (int)strlen(argv[1]);
    if(n > 256) return 2;
    for(int i = 0; i < n; i++) bits[i] = argv[1][i] == '1';

    char text[512];
    wiegand_format_binary_plain(bits, n, text, sizeof(text));
    printf("PLAIN<%s>\n", text);
    wiegand_format_binary_grouped(bits, n, text, sizeof(text));
    printf("GROUPED<%s>\n", text);
    wiegand_format_hex(bits, n, false, text, sizeof(text));
    printf("HEXR<%s>\n", text);
    wiegand_format_hex(bits, n, true, text, sizeof(text));
    printf("HEXL<%s>\n", text);
    wiegand_format_decode(bits, n, text, sizeof(text));
    printf("DECODE<%s>\n", text);
    printf("KNOWN<%d>\n", wiegand_format_known_length(n) ? 1 : 0);

    /* Small buffers must truncate, never overrun. */
    char tiny[5];
    memset(tiny, 'x', sizeof(tiny));
    wiegand_format_binary_plain(bits, n, tiny, 4);
    if(tiny[4] != 'x' || strlen(tiny) > 3) return 3;
    return 0;
}
